import { useEffect, useState } from "react";
import { useLocation } from "wouter";
import { useQueryClient } from "@tanstack/react-query";
import { Layout } from "@/components/layout";
import {
  CheckCircle2, Calendar, Clock, ArrowRight, Loader2, XCircle,
  Users, Copy, Check, Globe, Share2, ExternalLink, CreditCard,
} from "lucide-react";
import { Button } from "@/components/ui/button";
import { format } from "date-fns";

const BASE = import.meta.env.BASE_URL.replace(/\/$/, "");
const API = `${BASE}/api`;

interface BookingInfo {
  id: number;
  courtId: number;
  courtName?: string;
  date: string;
  startTime: string;
  endTime: string;
  totalPrice: number;
  customerName: string;
  status: string;
}

interface SplitConfirmInfo {
  bookingId: number;
  gameId: number | null;
  shareToken: string | null;
  pricePerSlot: number;
  totalSlots: number;
  paidSlots: number;
  totalPrice: number;
  date: string;
  startTime: string;
  endTime: string;
  sport: string | null;
  isPublic: boolean;
  courtId: number | null;
  courtName: string | null;
  courtImageUrl: string | null;
}

function formatBookingDate(value: string): string {
  const date = new Date(value);
  return Number.isNaN(date.getTime()) ? value : format(date, "yyyy-MM-dd");
}

function CopyButton({ text }: { text: string }) {
  const [copied, setCopied] = useState(false);
  const copy = () => {
    navigator.clipboard.writeText(text).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };
  return (
    <button
      onClick={copy}
      className="flex items-center gap-1 text-xs text-primary hover:text-primary/80 transition-colors ml-auto shrink-0"
    >
      {copied ? <Check className="w-3.5 h-3.5" /> : <Copy className="w-3.5 h-3.5" />}
      {copied ? "Nukopijuota!" : "Kopijuoti"}
    </button>
  );
}

function ShareButtons({ url, title }: { url: string; title: string }) {
  const [copied, setCopied] = useState(false);

  const handleNativeShare = async () => {
    if (navigator.share) {
      try {
        await navigator.share({ title, url });
      } catch {
        // user cancelled or API not supported
      }
    }
  };

  const handleCopy = () => {
    navigator.clipboard.writeText(url).then(() => {
      setCopied(true);
      setTimeout(() => setCopied(false), 2000);
    });
  };

  const waUrl = `https://wa.me/?text=${encodeURIComponent(`${title}\n${url}`)}`;
  const tgUrl = `https://t.me/share/url?url=${encodeURIComponent(url)}&text=${encodeURIComponent(title)}`;

  return (
    <div className="space-y-2">
      <p className="text-xs font-semibold text-muted-foreground uppercase tracking-wider">Dalintis</p>
      <div className="flex gap-2 flex-wrap">
        {typeof navigator !== "undefined" && "share" in navigator && (
          <Button size="sm" variant="outline" className="gap-1.5" onClick={handleNativeShare}>
            <Share2 className="w-3.5 h-3.5" />
            Dalintis
          </Button>
        )}
        <a
          href={waUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-1.5 h-9 px-3 rounded-md border border-border text-sm font-medium text-foreground hover:bg-muted transition-colors"
        >
          <span className="text-base leading-none">💬</span>
          WhatsApp
        </a>
        <a
          href={tgUrl}
          target="_blank"
          rel="noopener noreferrer"
          className="inline-flex items-center gap-1.5 h-9 px-3 rounded-md border border-border text-sm font-medium text-foreground hover:bg-muted transition-colors"
        >
          <span className="text-base leading-none">✈️</span>
          Telegram
        </a>
        <Button size="sm" variant="outline" className="gap-1.5" onClick={handleCopy}>
          {copied ? <Check className="w-3.5 h-3.5 text-green-500" /> : <Copy className="w-3.5 h-3.5" />}
          {copied ? "Nukopijuota!" : "Kopijuoti"}
        </Button>
      </div>
    </div>
  );
}

export default function BookingConfirmed() {
  const [, setLocation] = useLocation();
  const queryClient = useQueryClient();
  const params = new URLSearchParams(window.location.search);
  const bookingId = params.get("id");
